from PIL import Image
im = Image.open("/home/robot/captures/top_004.png")
px = im.load()
w,h = im.size
# fixture region from earlier visual: roughly x 280-430, y 180-280 in original
# find small dark dots: pixels darker than local background
cands = []
for y in range(160, 300):
    for x in range(270, 460):
        r,g,b = px[x,y]
        v = (r+g+b)/3
        if v > 80:
            continue
        # local background ring
        ring = []
        for dy in range(-6,7):
            for dx in range(-6,7):
                if 4 <= abs(dx)+abs(dy) <= 8:
                    rr,gg,bb = px[x+dx,y+dy]
                    ring.append((rr+gg+bb)/3)
        if not ring:
            continue
        bg = sum(ring)/len(ring)
        if bg - v > 30 and bg > 100:
            cands.append((x,y,v,bg))
print("cands", len(cands))
# cluster
clusters=[]
for s in cands:
    placed=False
    for c in clusters:
        if abs(c[0]-s[0])<8 and abs(c[1]-s[1])<8:
            n=c[2]
            c[0]=(c[0]*n+s[0])/(n+1)
            c[1]=(c[1]*n+s[1])/(n+1)
            c[2]=n+1
            c[3]=min(c[3], s[2])
            placed=True
            break
    if not placed:
        clusters.append([s[0],s[1],1,s[2]])
clusters.sort(key=lambda c:-c[2])
for c in clusters:
    print(f"cx={c[0]:.1f} cy={c[1]:.1f} n={c[2]} minv={c[3]:.0f}")

# also print pixels around gripper bottom
print("--- gripper bottom area ---")
# black bbox 308,198 - 355,245
for y in range(230, 270):
    row=[]
    for x in range(300, 370):
        r,g,b=px[x,y]
        v=(r+g+b)/3
        if v<40: row.append('#')
        elif v<90: row.append('*')
        elif v<130: row.append('+')
        elif v<160: row.append('.')
        else: row.append(' ')
    # only print rows with dark
    if '*' in row or '#' in row:
        print(f"{y:3d} {''.join(row)}")
