from PIL import Image

def analyze(path):
    im = Image.open(path)
    px = im.load()
    w,h = im.size
    spots=[]
    for y in range(10, h-10):
        for x in range(10, w-10):
            r,g,b=px[x,y]
            v=(r+g+b)/3
            if v>50: continue
            lighter=0; total=0
            for dy in range(-12,13,4):
                for dx in range(-12,13,4):
                    if abs(dx)<6 and abs(dy)<6: continue
                    rr,gg,bb=px[x+dx,y+dy]
                    total+=1
                    if (rr+gg+bb)/3 > 110:
                        lighter+=1
            if total and lighter/total>0.5 and v<45:
                spots.append((x,y))
    clusters=[]
    for s in spots:
        placed=False
        for c in clusters:
            if abs(c[0]-s[0])<15 and abs(c[1]-s[1])<15:
                n=c[2]
                c[0]=(c[0]*n+s[0])/(n+1)
                c[1]=(c[1]*n+s[1])/(n+1)
                c[2]=n+1
                placed=True
                break
        if not placed:
            clusters.append([s[0],s[1],1])
    clusters=[c for c in clusters if c[2]>10]
    clusters.sort(key=lambda c:(round(c[1]/20), c[0]))
    print(path, "nclusters", len(clusters))
    for c in clusters:
        print(f"  {c[0]:.1f},{c[1]:.1f} n={c[2]}")

for p in ["wrist_015","wrist_016","wrist_017","wrist_010","wrist_009"]:
    analyze(f"/home/robot/captures/{p}.png")
